//! The Parts: one `BlockPart` per Create block (and one `BlockEntityPart` per block that has an entity), each
//! forwarding its methods through `compat::events` into the old modules. Which blocks exist, and which have
//! entities, is generated by tools/gen_parts.py into `parts_gen.rs`.
use mod_api::{
    AnalogOutputEvent, BlockEntityPart, BlockEntityRenderBoundingBoxEvent, BlockEntitySubmitEvent, BlockEntityTickEvent,
    BlockEntityTicksEvent, BlockEntityUpdateTagEvent, BlockPart, BlockSignalEvent, BlockState, CanSurviveEvent,
    ClientHost, Compound, Flow, HasAnalogOutputEvent, Host, HostSide, InteractionResult, ItemPart, IsSignalSourceEvent, LevelHost,
    LevelSide, LevelTicksHost, LevelWriteHost, NeighborChangedEvent, ServerHost, StateForPlacementEvent,
    TickBlockEvent, UpdateShapeEvent, UseItemOnEvent,
};

use crate::compat::{events, items};

/// A Create block's `BlockPart`. `id` is the block's name without the namespace (`shaft`).
pub(crate) struct CreateBlock {
    pub id: &'static str,
}

#[mod_api::horizon_part]
impl BlockPart for CreateBlock {
    fn state_for_placement(
        &self,
        level: &dyn LevelHost,
        event: &mut StateForPlacementEvent<'_>,
    ) -> Option<Option<BlockState>> {
        events::state_for_placement(self.id, level, event)
    }
    fn can_survive(&self, level: &dyn LevelHost, event: &mut CanSurviveEvent) -> Option<bool> {
        events::can_survive(level, event)
    }
    fn update_shape(&self, level: &mut dyn LevelTicksHost, event: &mut UpdateShapeEvent) -> Option<BlockState> {
        events::update_shape(level, event)
    }
    fn neighbor_changed(&self, level: &mut dyn LevelTicksHost, event: &mut NeighborChangedEvent) {
        events::neighbor_changed(level, event)
    }
    fn tick_block(&self, level: &mut dyn LevelWriteHost, event: &mut TickBlockEvent) -> Flow {
        events::tick_block(level, event)
    }
    fn block_signal(&self, level: &dyn LevelHost, event: &mut BlockSignalEvent) {
        events::block_signal(level, event)
    }
    fn is_signal_source(&self, level: &dyn LevelHost, event: &mut IsSignalSourceEvent) {
        events::is_signal_source(level, event)
    }
    fn has_analog_output(&self, level: &dyn LevelHost, event: &mut HasAnalogOutputEvent) {
        events::has_analog_output(level, event)
    }
    fn analog_output(&self, level: &dyn LevelHost, event: &mut AnalogOutputEvent) {
        events::analog_output(level, event)
    }
    fn use_item_on(&self, host: &mut dyn ServerHost, event: &mut UseItemOnEvent<'_>) -> Option<InteractionResult> {
        events::use_item_on(host, event)
    }
}

/// A Create block entity's `BlockEntityPart`. `id` is the block's name; the block entity type has the same name.
pub(crate) struct CreateEntity {
    pub id: &'static str,
}

// A block entity part extends BlockPart, so it carries an (empty) BlockPart impl of its own.
#[mod_api::horizon_part]
impl BlockPart for CreateEntity {}

#[mod_api::horizon_part]
impl BlockEntityPart for CreateEntity {
    fn block_entity(&self, _level: LevelSide, event: &mut mod_api::BlockEntityEvent<'_>) -> Option<Compound> {
        events::block_entity(self.id, event.state)
    }
    fn block_entity_ticks(&self, host: &dyn Host, event: &mut BlockEntityTicksEvent<'_>) {
        event.ticks = events::block_entity_ticks(host, self.id);
    }
    fn block_entity_tick(&self, host: &mut dyn ServerHost, event: &mut BlockEntityTickEvent<'_>) {
        events::block_entity_tick(host, event)
    }
    fn block_entity_update_tag(&self, event: &mut BlockEntityUpdateTagEvent<'_>) -> Option<Compound> {
        events::block_entity_update_tag(event)
    }
    fn block_entity_submit(&self, host: &dyn ClientHost, event: &mut BlockEntitySubmitEvent<'_>) {
        events::block_entity_submit(host, event)
    }
    fn block_entity_render_bounding_box(&self, host: &dyn ClientHost, event: &mut BlockEntityRenderBoundingBoxEvent<'_>) {
        events::block_entity_render_bounding_box(host, event)
    }
}

/// A Create item's `ItemPart` (every item the content declares, and every block that has an item). `id` is the
/// item's full name; the old modules answer by the stack's item name, so the Part only forwards.
pub(crate) struct CreateItem {
    #[allow(dead_code)]
    pub id: &'static str,
}

#[mod_api::horizon_part]
impl ItemPart for CreateItem {
    fn tooltip(&self, host: &dyn ClientHost, event: &mut mod_api::TooltipEvent<'_>) {
        items::tooltip(host, event)
    }
    fn use_item(&self, host: HostSide, event: &mut mod_api::UseItemEvent<'_>) -> Option<InteractionResult> {
        items::use_item(host, event)
    }
    fn inventory_tick(&self, host: &mut dyn ServerHost, event: &mut mod_api::InventoryTickEvent<'_>) {
        items::inventory_tick(host, event)
    }
    fn item_bar(&self, host: &dyn ClientHost, event: &mut mod_api::ItemBarEvent<'_>) {
        items::item_bar(host, event)
    }
    fn use_duration(&self, host: &dyn Host, event: &mut mod_api::UseDurationEvent<'_>) {
        items::use_duration(host, event)
    }
    fn use_animation(&self, host: &dyn ClientHost, event: &mut mod_api::UseAnimationEvent<'_>) {
        items::use_animation(host, event)
    }
    fn release_using(&self, host: HostSide, event: &mut mod_api::ReleaseUsingEvent<'_>) {
        items::release_using(host, event)
    }
}
